const $=id=>document.getElementById(id),empty=()=>({values:Array(81).fill(0),notes:Array.from({length:81},()=>[])});
let hint=null,hintRevealed=false;
let initial=empty(),state=empty(),selected=0,mode='value',history=[],pendingConfirm=null,photo=null,ocrBusy=false;
try{const saved=localStorage.getItem('sudoku-notatnik-v1');if(saved)state=Sudoku.validate(JSON.parse(saved));}catch{}
try{const saved=localStorage.getItem('sudoku-notatnik-initial-v1');initial=saved?Sudoku.validate(JSON.parse(saved)):Sudoku.validate({values:state.values});}catch{initial=empty();}
function message(text){$('status').textContent=text;}
function save(){try{localStorage.setItem('sudoku-notatnik-v1',JSON.stringify(state));localStorage.setItem('sudoku-notatnik-initial-v1',JSON.stringify(initial));}catch{message('Nie udało się zapisać na urządzeniu. Możesz pobrać planszę do pliku.');}}
function change(fn){clearHint();history.push(JSON.stringify({state,initial}));fn();save();render();}
function confirmAction(title,description,action){$('confirm-title').textContent=title;$('confirm-description').textContent=description;pendingConfirm=action;$('confirm-dialog').showModal();}
$('confirm-no').onclick=()=>$('confirm-dialog').close();$('confirm-yes').onclick=()=>{const fn=pendingConfirm;pendingConfirm=null;$('confirm-dialog').close();fn?.();};
const cells=Array.from({length:81},(_,i)=>{const b=document.createElement('button');b.className='cell';b.onclick=()=>{selected=i;render();};b.onfocus=()=>{if(selected!==i){selected=i;render();}};$('board').append(b);return b;});
function render(){const bad=Sudoku.conflicts(state.values),filled=state.values.filter(Boolean).length;cells.forEach((b,i)=>{b.className='cell'+(Sudoku.peers(selected,i)?' peer':'')+(state.values[selected]&&state.values[i]===state.values[selected]?' same':'')+(selected===i?' selected':'')+(bad[i]?' conflict':'')+(hintRevealed&&hint?.sources.includes(i)?' hint-source':'')+(hintRevealed&&hint?.targets.includes(i)?' hint-target':'');b.tabIndex=selected===i?0:-1;b.setAttribute('aria-label',`Wiersz ${Math.floor(i/9)+1}, kolumna ${i%9+1}: ${state.values[i]||'puste'}${!state.values[i]&&state.notes[i].length?', kandydaci '+state.notes[i].join(', '):''}${bad[i]?', konflikt':''}`);b.setAttribute('aria-pressed',String(selected===i));b.replaceChildren();if(state.values[i])b.textContent=state.values[i];else{const notes=document.createElement('span');notes.className='notes';for(let n=1;n<=9;n++){const x=document.createElement('span');x.textContent=state.notes[i].includes(n)?n:'';notes.append(x);}b.append(notes);}});$('filled').textContent=`${filled} / 81 pól`;$('board-state').textContent=bad.some(Boolean)?'Konflikt liczb':filled===81?'Sudoku ukończone ✓':filled?'W trakcie':'Pusta plansza';$('undo').disabled=!history.length;$('value-mode').classList.toggle('active',mode==='value');$('note-mode').classList.toggle('active',mode==='note');$('value-mode').setAttribute('aria-pressed',String(mode==='value'));$('note-mode').setAttribute('aria-pressed',String(mode==='note'));$('mode-help').textContent=mode==='value'?'Wpisz cyfrę w wybranym polu.':'Kliknij cyfrę, aby dodać lub usunąć kandydata.';}
function clearHint(){hint=null;hintRevealed=false;$('hint-result').hidden=true;$('hint-name').textContent='';$('hint-explanation').textContent='';$('hint-explanation').hidden=true;$('hint-legend').hidden=true;$('hint-reveal').hidden=true;}
$('hint-technique').onclick=()=>{clearHint();const found=SudokuHints.findHint(state.values);$('hint-result').hidden=false;if(found.kind==='hint'){hint=found;$('hint-name').textContent='Technika: '+found.technique;$('hint-reveal').hidden=false;}else $('hint-name').textContent=found.message;render();};
$('hint-reveal').onclick=()=>{if(!hint)return;hintRevealed=true;$('hint-explanation').textContent=hint.explanation;$('hint-explanation').hidden=false;$('hint-legend').hidden=!hint.targets.length;$('hint-reveal').hidden=true;render();$('board').scrollIntoView({behavior:'smooth',block:'nearest'});};
$('hint-dismiss').onclick=()=>{clearHint();render();};
function setMode(m){mode=m;render();}
function enter(n){if(mode==='note'&&state.values[selected]){message('Aby dodać kandydatów, najpierw usuń liczbę z tego pola.');return;}change(()=>{if(mode==='value'){Sudoku.placeValue(state,selected,n);}else{const a=state.notes[selected];state.notes[selected]=a.includes(n)?a.filter(x=>x!==n):[...a,n].sort();}});message(mode==='note'?'Zmieniono kandydatów w wybranym polu.':'Wpisano liczbę i zaktualizowano kandydatów w wierszu, kolumnie i kwadracie 3 × 3.');}
for(let n=1;n<=9;n++){const b=document.createElement('button');b.textContent=n;b.setAttribute('aria-label',`Wpisz ${n}`);b.onclick=()=>enter(n);$('keypad').append(b);}
$('value-mode').onclick=()=>setMode('value');$('note-mode').onclick=()=>setMode('note');
$('erase').onclick=()=>{change(()=>{state.values[selected]=0;state.notes[selected]=[];});message('Wyczyszczono wybrane pole.');};
$('undo').onclick=()=>{if(history.length){clearHint();const previous=JSON.parse(history.pop());state=previous.state;initial=previous.initial;save();render();message('Cofnięto ostatnią zmianę.');}};
$('calculate').onclick=()=>{change(()=>{state.notes=state.values.map((_,i)=>Sudoku.candidates(state.values,i));});const impossible=state.values.some((v,i)=>!v&&!state.notes[i].length);message(Sudoku.conflicts(state.values).some(Boolean)?'Obliczono kandydatów. Popraw zaznaczone na czerwono konflikty.':impossible?'Obliczono kandydatów. Co najmniej jedno puste pole nie ma możliwej cyfry — sprawdź wpisane liczby.':'Obliczono kandydatów. Możesz teraz edytować ich w trybie „Kandydaci”.');};
function replace(data,label){const apply=()=>{change(()=>{state=structuredClone(data);initial=Sudoku.validate({values:data.values});});selected=0;render();message(label);};if(state.values.some(Boolean)||state.notes.some(a=>a.length))confirmAction('Zastąpić obecną planszę?','Bieżąca plansza i notatki zostaną zastąpione. Zmianę możesz cofnąć przyciskiem „Cofnij”.',apply);else apply();}
$('clear-notes').onclick=()=>{change(()=>{state.notes=Array.from({length:81},()=>[]);});message('Wyczyszczono wszystkich kandydatów. Liczby pozostały na planszy.');};
$('restart').onclick=()=>confirmAction('Rozpocząć sudoku od początku?','Przywrócisz liczby z ostatniego importu lub przykładu i usuniesz kandydatów. Na planszy rozpoczętej ręcznie usunięte zostaną wszystkie wpisy. Możesz cofnąć restart.',()=>{change(()=>{state=structuredClone(initial);});message('Przywrócono początkową planszę. Restart możesz cofnąć.');});
$('reset').onclick=()=>replace(empty(),'Gotowe. Nowa plansza czeka na pierwszą liczbę.');
$('example').onclick=()=>replace(Sudoku.parse('530070000600195000098000060800060003400803001700020006060000280000419005000080079'),'Wczytano przykład. Oblicz kandydatów lub wpisz własne notatki.');
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||/INPUT|TEXTAREA/.test(e.target.tagName)||e.altKey)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();$('undo').click();return;}if(e.ctrlKey||e.metaKey)return;if(/^[1-9]$/.test(e.key)){e.preventDefault();enter(Number(e.key));}else if(['Backspace','Delete','0','.'].includes(e.key)){e.preventDefault();$('erase').click();}else if(e.key.toLowerCase()==='n'){e.preventDefault();setMode(mode==='value'?'note':'value');}else if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const r=Math.floor(selected/9),c=selected%9;selected=e.key==='ArrowUp'?Math.max(0,r-1)*9+c:e.key==='ArrowDown'?Math.min(8,r+1)*9+c:e.key==='ArrowLeft'?r*9+Math.max(0,c-1):r*9+Math.min(8,c+1);render();cells[selected].focus();}});
$('import-text').onclick=()=>{$('text-error').textContent='';$('text-dialog').showModal();};$('choose-text').onclick=()=>$('text-file').click();$('apply-text').onclick=()=>{try{const data=Sudoku.parse($('text-input').value);$('text-dialog').close();replace(data,'Wczytano planszę z tekstu.');}catch(e){$('text-error').textContent=e.message;}};
$('text-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>1024*1024)throw Error('Plik tekstowy jest zbyt duży (maks. 1 MB).');const text=await f.text();const data=Sudoku.parse(text);$('text-dialog').close();replace(data,'Wczytano planszę z pliku.');}catch(err){$('text-error').textContent=err.message;}e.target.value='';};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({...state,format:'sudoku-notatnik-v1'},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='sudoku-notatnik.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message('Pobrano planszę i kandydatów. Możesz przywrócić je opcją „Z tekstu” → „Wybierz plik”.');};
$('import-image').onclick=()=>$('image-file').click();
function crop(){const size=Math.min(photo.width,photo.height)*Number($('crop-size').value)/100;return {size,x:(photo.width-size)*Number($('crop-x').value)/100,y:(photo.height-size)*Number($('crop-y').value)/100};}
function drawPhoto(){if(!photo)return;const c=$('image-preview'),ctx=c.getContext('2d'),scale=600/Math.max(photo.width,photo.height);c.width=Math.round(photo.width*scale);c.height=Math.round(photo.height*scale);ctx.drawImage(photo,0,0,c.width,c.height);ctx.fillStyle='#142b2960';ctx.fillRect(0,0,c.width,c.height);const {size,x,y}=crop();ctx.drawImage(photo,x,y,size,size,x*scale,y*scale,size*scale,size*scale);ctx.strokeStyle='#91bf65';ctx.lineWidth=2;ctx.strokeRect(x*scale,y*scale,size*scale,size*scale);ctx.lineWidth=.7;for(let n=1;n<9;n++){ctx.beginPath();ctx.moveTo((x+size*n/9)*scale,y*scale);ctx.lineTo((x+size*n/9)*scale,(y+size)*scale);ctx.moveTo(x*scale,(y+size*n/9)*scale);ctx.lineTo((x+size)*scale,(y+size*n/9)*scale);ctx.stroke();}}
for(const id of ['crop-size','crop-x','crop-y'])$(id).oninput=()=>{drawPhoto();$('ocr-review').hidden=true;$('apply-image').hidden=true;};
async function openPhoto(source){const next=await createImageBitmap(source);photo?.close?.();photo=next;$('crop-size').value=90;$('crop-x').value=50;$('crop-y').value=50;$('ocr-status').textContent='Dopasuj ramkę do zewnętrznych krawędzi siatki. OCR działa w przeglądarce; pobranie silnika wymaga internetu.';$('ocr-review').hidden=true;$('apply-image').hidden=true;drawPhoto();$('image-dialog').showModal();}
async function importPhotoFile(e){const file=e.target.files[0];if(!file)return;try{if(file.size>20*1024*1024)throw Error('Obraz jest zbyt duży. Wybierz plik do 20 MB.');await openPhoto(file);}catch(err){message('Nie udało się otworzyć obrazu. '+err.message);}finally{e.target.value='';}}
$('image-file').onchange=importPhotoFile;
$('camera-file').onchange=importPhotoFile;
let enginePromise;
function loadEngine(){if(!enginePromise)enginePromise=new Promise((resolve,reject)=>{if(window.Tesseract)return resolve(window.Tesseract);const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js';script.onload=()=>resolve(window.Tesseract);script.onerror=()=>{enginePromise=null;script.remove();reject(Error('Nie można pobrać silnika OCR. Sprawdź połączenie z internetem.'));};document.head.append(script);});return enginePromise;}
$('image-dialog').addEventListener('cancel',e=>{if(ocrBusy)e.preventDefault();});
$('recognize').onclick=async()=>{if(!photo||ocrBusy)return;ocrBusy=true;$('recognize').disabled=true;$('apply-image').hidden=true;$('ocr-review').hidden=true;document.querySelectorAll('#image-dialog input,#image-dialog .close').forEach(e=>e.disabled=true);let worker;try{$('ocr-status').textContent='Pobieranie i uruchamianie silnika OCR…';const T=await loadEngine();worker=await T.createWorker('eng');await worker.setParameters({tessedit_char_whitelist:'123456789',tessedit_pageseg_mode:'10'});const {size,x,y}=crop(),step=size/9,c=document.createElement('canvas');c.width=c.height=100;const ctx=c.getContext('2d'),values=Array(81).fill(0);for(let i=0;i<81;i++){$('ocr-status').textContent=`Rozpoznawanie pola ${i+1} z 81…`;ctx.fillStyle='white';ctx.fillRect(0,0,100,100);ctx.drawImage(photo,x+(i%9+.12)*step,y+(Math.floor(i/9)+.12)*step,step*.76,step*.76,16,16,68,68);const pixels=ctx.getImageData(0,0,100,100);let dark=0;for(let p=0;p<pixels.data.length;p+=4){const lum=(pixels.data[p]+pixels.data[p+1]+pixels.data[p+2])/3;const v=lum<150?0:255;pixels.data[p]=pixels.data[p+1]=pixels.data[p+2]=v;if(!v)dark++;}ctx.putImageData(pixels,0,0);if(dark>45){const result=await worker.recognize(c);const digit=result.data.text.trim();if(/^[1-9]$/.test(digit))values[i]=Number(digit);}}$('review-grid').replaceChildren();values.forEach((v,i)=>{const input=document.createElement('input');input.type='text';input.inputMode='numeric';input.maxLength=1;input.value=v||'';input.setAttribute('aria-label',`Wiersz ${Math.floor(i/9)+1}, kolumna ${i%9+1}`);input.oninput=()=>input.value=input.value.replace(/[^1-9]/g,'').slice(0,1);$('review-grid').append(input);});$('ocr-review').hidden=false;$('apply-image').hidden=false;$('ocr-status').textContent=`Rozpoznano ${values.filter(Boolean).length} cyfr. Sprawdź wynik z obrazkiem i popraw ewentualne pomyłki.`;}catch(err){$('ocr-status').textContent='Rozpoznawanie nie powiodło się. '+err.message;}finally{if(worker)await worker.terminate();ocrBusy=false;$('recognize').disabled=false;document.querySelectorAll('#image-dialog input,#image-dialog .close').forEach(e=>e.disabled=false);}};
$('apply-image').onclick=()=>{const data=empty();data.values=[...$('review-grid').children].map(x=>Number(x.value)||0);$('image-dialog').close();replace(data,'Wczytano sprawdzoną planszę z obrazka.');};
render();

// Keep a single set of editing controls; relocate it next to the board on phones.
const phoneLayout=window.matchMedia('(max-width: 640px)');
function positionEntryControls(){
 const entry=$('entry-controls'),undo=$('undo');
 if(phoneLayout.matches){$('mobile-entry-slot').append(entry);entry.append(undo);}
 else{$('desktop-entry-slot').append(entry);$('desktop-undo-slot').append(undo);}
}
phoneLayout.addEventListener('change',positionEntryControls);
positionEntryControls();
